import sys
from enum import IntEnum
from typing import Any

from evaluation.tree_decomposition import NiceTreeDecomposition, TreeDecomposition

# Autogenerated.


class InputVariableType(IntEnum):
    INT = 0
    INT_LIST = 1
    GRAPH = 2
    TREE_DECOMPOSITION = 3

    def __repr__(self):
        return f"InputVariableType.{self.name}"


def read_tree_decomposition() -> TreeDecomposition:
    input = sys.stdin.readline
    num_bags = int(input())
    num_edges = int(input())

    b = [set() for _ in range(num_bags)]
    e2b = [(0, 0) for _ in range(num_edges)]

    for i in range(num_bags):
        b[i] = set(map(int, input().split(" ")))

    for i in range(num_edges):
        j, k = map(int, input().split(" "))
        assert j < k
        e2b[i] = (j, k)

    assert len(b) == num_bags
    assert len(e2b) == num_edges

    return TreeDecomposition(b=b, e2b=e2b)


def read_graph() -> tuple[int, int, list[tuple[int, int]]]:
    input = sys.stdin.readline
    n = int(input())
    m = int(input())
    edges = [tuple(map(int, input().split(" "))) for _ in range(m)]
    assert len(edges) == m
    return (n, m, edges)


def read_int_list() -> list[int]:
    input = sys.stdin.readline
    length = int(input())  # length
    result = list(map(int, input().split()))
    assert len(result) == length
    return result


def read_int() -> int:
    input = sys.stdin.readline
    return int(input())


def input_td_to_ntd(
    unused: Any,
    *,
    tree_decomposition: TreeDecomposition,
) -> NiceTreeDecomposition:
    return NiceTreeDecomposition(tree_decomposition)


def _read_inputs(varz: list[tuple[str, InputVariableType]]) -> dict[str, Any]:
    inputs = {}
    for name, type in varz:
        if type == InputVariableType.INT:
            inputs[name] = read_int()
        elif type == InputVariableType.INT_LIST:
            inputs[name] = read_int_list()
        elif type == InputVariableType.GRAPH:
            inputs[name] = read_graph()
        elif type == InputVariableType.TREE_DECOMPOSITION:
            inputs[name] = read_tree_decomposition()
    return inputs


def read_inputs() -> dict[str, Any]:
    varz = [
        ("n", InputVariableType.INT),
        ("x_s", InputVariableType.INT_LIST),
        ("graph", InputVariableType.GRAPH),
        ("tree_decomposition", InputVariableType.TREE_DECOMPOSITION),
    ]
    return _read_inputs(varz)
